/**
 * Schema v1 — public data types.
 *
 * A document is a plain JSON object: metadata plus a flat block map with
 * explicit ordering via `children`. The JSON form and the CRDT form are
 * isomorphic: every field has exactly one CRDT image.
 */

/** Block identifier (nanoid, generated by the change author; never reused). */
type BlockId = string;

/** The set of marks applied to a run. */
interface MarkSet {
  bold?: true;
  italic?: true;
  strike?: true;
  underline?: true;
  /** Exclusive: never coexists with other marks on the same run. */
  code?: true;
  /** http/https URL or relative path. */
  link?: { href: string };
  /** Text color, hex `#RRGGBB` (alpha optional). */
  color?: { value: string };
  /** Text highlight, hex `#RRGGBB` (alpha optional). */
  highlight?: { value?: string };
  /** Inline formula (KaTeX-compatible source). Exclusive. */
  math?: { tex: string };
}

/** All mark names. */
type MarkName = keyof MarkSet;

/** An inline text run: a span of text with the marks applied to it. */
interface TextRun {
  text: string;
  marks: MarkSet;
}

/** Inline text content of a block: an array of runs. */
type BlockContent = TextRun[];

/** Document metadata. */
interface DocMeta {
  /** Schema version. */
  v: 1;
  /** Document identifier (nanoid). */
  id: string;
  /** Document title (empty string is a valid state). */
  title: string;
  /** Creation time, ISO 8601. */
  createdAt: string;
}

/** Document in the public JSON format. */
interface DocJSON extends DocMeta {
  /** Flat map: block id -> block. Order lives in `children`. */
  blocks: Record<BlockId, Block>;
}

interface HeadingAttrs {
  /** Heading level 1-6. */
  level: 1 | 2 | 3 | 4 | 5 | 6;
}

interface ListItemAttrs {
  list: "bullet" | "number" | "task";
  checked?: boolean;
}

interface CalloutAttrs {
  variant?: "info" | "warning" | "danger";
}

interface CodeAttrs {
  language?: string;
}

interface LatexAttrs {
  /** Display (block) formula vs inline. */
  display: boolean;
}

interface TableAttrs {
  /** Column count; every row holds exactly `cols` cells. */
  cols: number;
}

interface ImageAttrs {
  /** Opaque blob key (resolved by the consumer). */
  src: string;
  /** Width in px; `null` = natural width. */
  width?: number | null;
  align?: "left" | "center" | "right";
}

interface RootBlock {
  type: "root";
  /** Top-level page blocks, in reading order. */
  children: BlockId[];
}

interface ParagraphBlock {
  type: "paragraph";
  content?: BlockContent;
}

interface HeadingBlock {
  type: "heading";
  attrs: HeadingAttrs;
  content?: BlockContent;
}

interface ListItemBlock {
  type: "list-item";
  attrs: ListItemAttrs;
  content?: BlockContent;
  /** Nested `list-item` blocks only. */
  children?: BlockId[];
}

interface CalloutBlock {
  type: "callout";
  attrs?: CalloutAttrs;
  content?: BlockContent;
}

interface CodeBlock {
  type: "code";
  attrs?: CodeAttrs;
  content?: BlockContent;
}

interface LatexBlock {
  type: "latex";
  attrs: LatexAttrs;
  /** Text is the LaTeX source. */
  content?: BlockContent;
}

interface TableBlock {
  type: "table";
  attrs: TableAttrs;
  /** `table-row` blocks only. */
  children?: BlockId[];
}

interface TableRowBlock {
  type: "table-row";
  /** `table-cell` blocks only; exactly the table `cols` count. */
  children?: BlockId[];
}

interface TableCellBlock {
  type: "table-cell";
  /** Empty content is a valid (empty) cell. */
  content?: BlockContent;
  /** Leaf block types only. */
  children?: BlockId[];
}

interface ImageBlock {
  type: "image";
  attrs: ImageAttrs;
}

interface DividerBlock {
  type: "divider";
}

/** All v1 block types. */
type Block =
  | RootBlock
  | ParagraphBlock
  | HeadingBlock
  | ListItemBlock
  | CalloutBlock
  | CodeBlock
  | LatexBlock
  | TableBlock
  | TableRowBlock
  | TableCellBlock
  | ImageBlock
  | DividerBlock;

/** Block type discriminator. */
type BlockType = Block["type"];

export type {
  Block,
  BlockContent,
  BlockId,
  BlockType,
  CalloutAttrs,
  CalloutBlock,
  CodeAttrs,
  CodeBlock,
  DocJSON,
  DocMeta,
  DividerBlock,
  HeadingAttrs,
  HeadingBlock,
  ImageAttrs,
  ImageBlock,
  LatexAttrs,
  LatexBlock,
  ListItemAttrs,
  ListItemBlock,
  MarkName,
  MarkSet,
  ParagraphBlock,
  RootBlock,
  TableAttrs,
  TableBlock,
  TableCellBlock,
  TableRowBlock,
  TextRun,
};
